const std = @import("std"); const hash = @import("ut-hash-dedu.zig"); const Ipzz = std.Io.net.IpAddress; const Host = std.Io.net.HostName;
const CF = .{ .hopz = 16, .bsuf = @as([]const []const u8, &.{ ".localhost", ".local", ".internal", ".lan", ".home", ".corp", ".intranet", ".localdomain" }) };
pub fn ipv4Bloc(addr: [4]u8) bool { const abzz = addr[0]; const bbzz = addr[1]; return abzz == 0 or abzz == 10 or abzz == 127 or abzz >= 224 or (abzz == 100 and bbzz >= 64 and bbzz <= 127) or (abzz == 169 and bbzz == 254) or (abzz == 172 and bbzz >= 16 and bbzz <= 31) or (abzz == 192 and bbzz == 168) or (abzz == 192 and bbzz == 0 and addr[2] == 0) or (abzz == 198 and (bbzz == 18 or bbzz == 19)) or (abzz == 192 and bbzz == 0 and addr[2] == 2) or (abzz == 198 and bbzz == 51 and addr[2] == 100) or (abzz == 203 and bbzz == 0 and addr[2] == 113); }
pub fn ipv6Bloc(addr: [16]u8) bool { const zero = @as([10]u8, @splat(0)); if (std.mem.eql(u8, addr[0..10], &zero) and addr[10] == 0xff and addr[11] == 0xff) return ipv4Bloc(addr[12..16].*); if (std.mem.eql(u8, addr[0..12], &[_]u8{ 0, 0x64, 0xff, 0x9b, 0, 0, 0, 0, 0, 0, 0, 0 })) return ipv4Bloc(addr[12..16].*); if (std.mem.eql(u8, addr[0..15], &(@as([15]u8, @splat(0))))) return addr[15] <= 1; if (std.mem.eql(u8, addr[0..12], &(@as([12]u8, @splat(0))))) return true; return (addr[0] & 0xfe) == 0xfc or (addr[0] == 0xfe and (addr[1] & 0xc0) == 0x80) or addr[0] == 0xff or (addr[0] == 0x20 and addr[1] == 0x01 and addr[2] == 0x0d and addr[3] == 0xb8) or (addr[0] == 0x01 and addr[1] == 0 and std.mem.eql(u8, addr[2..8], &(@as([6]u8, @splat(0))))); }
pub fn ipzzBloc(addr: Ipzz) bool { return switch (addr) { .ip4 => |each| ipv4Bloc(each.bytes), .ip6 => |each| ipv6Bloc(each.bytes) }; }
fn nameBloc(host: []const u8) bool { if (std.mem.findScalar(u8, host, '.') == null) return true; if (std.ascii.eqlIgnoreCase(host, "localhost")) return true; for (CF.bsuf) |suff| if (std.ascii.endsWithIgnoreCase(host, suff)) return true; return false; }
fn numbOddz(host: []const u8) bool { const dotz = std.mem.findScalarLast(u8, host, '.'); const last = if (dotz) |dzzz| host[dzzz + 1 ..] else host; if (last.len == 0) return true; if (std.ascii.startsWithIgnoreCase(last, "0x")) return true; for (last) |byte| if (!std.ascii.isDigit(byte)) return false; return true; }
pub fn hostChek(ioz2: std.Io, host: []const u8, priv: bool) !void { var name = host; if (name.len > 2 and name[0] == '[' and name[name.len - 1] == ']') name = name[1 .. name.len - 1]; if (name.len == 0) return error.BlockedHost; if (std.mem.findScalar(u8, name, ':') != null or std.mem.findScalar(u8, name, '%') != null) { const addr = Ipzz.parse(std.mem.sliceTo(name, '%'), 0) catch return error.BlockedHost; if (!priv and ipzzBloc(addr)) return error.BlockedHost; return; } if (Ipzz.parse(name, 0)) |addr| { if (!priv and ipzzBloc(addr)) return error.BlockedHost; return; } else |_| {} if (numbOddz(name)) return error.BlockedHost; if (!priv and nameBloc(name)) return error.BlockedHost; if (priv) return; const hos3 = Host.init(name) catch return error.BlockedHost; var buff: [16]Host.LookupResult = undefined; var quez: std.Io.Queue(Host.LookupResult) = .init(&buff); hos3.lookup(ioz2, &quez, .{ .port = 443 }) catch return error.BlockedHost; var seen: u32 = 0; while (quez.getOne(ioz2)) |item| { switch (item) { .address => |addr| { seen += 1; if (ipzzBloc(addr)) return error.BlockedHost; }, .canonical_name => {} } } else |_| {} if (seen == 0) return error.BlockedHost; }
pub const Hops = struct { seen: [CF.hopz]hash.Hexz = undefined, lenz: usize = 0, maxz: usize = 5,
pub fn visi(self: *Hops, urlz: []const u8) !void { const hexz = hash.hashHexz(urlz); for (self.seen[0..self.lenz]) |item| if (std.mem.eql(u8, &item, &hexz)) return error.RedirectLoop; if (self.lenz >= self.maxz or self.lenz >= CF.hopz) return error.TooManyRedirects; self.seen[self.lenz] = hexz; self.lenz += 1; } };
